\[
\begin{array}{c@{}c@{}c@{}c}
 & 1 & 5 & & \\
1 & 4 & 4 & & \text{(Original numbers)} \\
+ & \underline{2} & 0 & & \text{(Converted 8 to base 6)} \\
2 & 2 & 2 & & \text{(Result in base 6)}
\end{array}
\]
